import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date format validation
        if (startDate == null || !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate == null || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Department parameter is optional but used in query construction
        String query = buildQuery(reportType, startDate, endDate, department);
        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String type, String start, String end, String dept) {
        StringBuilder sb = new StringBuilder();
        switch (type) {
            case "summary":
                sb.append("SELECT department, COUNT(*) as cnt, SUM(amount) as total ");
                sb.append("FROM transactions WHERE tx_date BETWEEN '");
                sb.append(start).append("' AND '").append(end).append("'");
                break;
            case "detail":
                sb.append("SELECT id, department, amount, description, tx_date ");
                sb.append("FROM transactions WHERE tx_date BETWEEN '");
                sb.append(start).append("' AND '").append(end).append("'");
                break;
            case "audit":
                sb.append("SELECT id, user_id, action, timestamp ");
                sb.append("FROM audit_log WHERE timestamp BETWEEN '");
                sb.append(start).append("' AND '").append(end).append("'");
                break;
        }
        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }
        if ("summary".equals(type)) {
            sb.append(" GROUP BY department");
        }
        sb.append(" LIMIT 1000");
        return sb.toString();
    }
}
